from magier_ambient_catalog import RACES
from magier_voice_banks import theme_for

GERMAN = {"GNOME":{"FIRE":["Die Temperaturkurve ist prächtig. Die Sicherheitskurve eher nicht.","*kalibriert eine Feuerkugel anhand winziger Messskalen.*"],"FROST":["Bei exakt minus siebenunddreißig Grad sollte das funktionieren.","*misst die entstehende Eisschicht mit einem Tascheninstrument.*"],"ARCANE":["Meine Gleichung stimmt! Diesmal sogar in der Praxis.","*lässt violette Runen wie Zahnräder ineinandergreifen.*"]},"HUMAN":{"FIRE":["Konzentrierte Flammen, keine sinnlose Zerstörung.","*formt die Flamme mit disziplinierter Geste.*"],"FROST":["Geduld lässt selbst den Winter gehorchen.","*zeichnet mit ruhiger Hand ein klares Eissiegel.*"],"ARCANE":["Die erste Regel lautet: Kontrolle vor Kraft.","*rezitiert eine Formel aus der Akademie.*"]},"HIGH_ELF":{"FIRE":["Diese Flamme trägt noch das Wissen alter Zeitalter.","*webt einen feinen goldenen Feuerfaden.*"],"FROST":["Ein Winterhauch aus vergessenen Jahrhunderten.","*streift mit der Hand über uralte Frostglyphen.*"],"ARCANE":["Die Leylinien erinnern sich an jeden unserer Schritte.","*lauscht kurz dem Gesang der arkanen Ströme.*"]},"BLOODELF":{"FIRE":["Seht die Eleganz einer vollkommenen Flamme.","*modelliert eine makellose Feuerrose.*"],"FROST":["Selbst Eis kann eine Frage des Stils sein.","*schafft eine kristallene, symmetrische Frostfigur.*"],"ARCANE":["Arkane Vollkommenheit verlangt ein sicheres Händchen.","*richtet schimmernde Runen bis auf den letzten Winkel aus.*"]},"NIGHTELF":{"FIRE":["Selbst die Flamme soll das Gleichgewicht achten.","*lenkt das Feuer behutsam zwischen die Blätter.*"],"FROST":["Die stille Kälte erinnert an sternklare Nächte.","*hebt schimmernden Reif vom Waldboden.*"],"ARCANE":["Alte Mächte sollten niemals leichtfertig geweckt werden.","*lauscht der Stille zwischen den Leylinien.*"]},"UNDEAD":{"FIRE":["Wärme. Eine beinahe nostalgische Angelegenheit.","*betrachtet das Feuer mit unbewegter Miene.*"],"FROST":["Kälte ist mir seit Jahren vertraut.","*lässt Eis über knochige Finger wandern.*"],"ARCANE":["Wissen verwest langsamer als Fleisch.","*blättert in einem staubigen Grimoire.*"]},"TROLL":{"FIRE":["Die Ahnen mögen diese Flamme lenken.","*zeichnet ein glühendes Zeichen der alten Geister.*"],"FROST":["Auch die kalten Winde hören auf die Ahnen.","*murmelt einen alten Namen zwischen eisigen Funken.*"],"ARCANE":["Magie ist älter als jedes Buch, Freundchen.","*verbindet ein altes Zeichen mit arkanen Runen.*"]},"ORC":{"FIRE":["Eine starke Flamme braucht eine stärkere Hand.","*packt die Magie mit entschlossener Geste.*"],"FROST":["Stillstand kann die stärkste Waffe sein.","*rammt eine eisige Rune in die Luft.*"],"ARCANE":["Kraft ohne Verstand verschwendet Mana.","*hält einen unruhigen Zauber mit festem Willen zusammen.*"]},"DRAENEI":{"FIRE":["Möge diese Flamme schützen, nicht verzehren.","*hüllt einen Funken in sanftes Licht.*"],"FROST":["Geduld findet selbst im Winter einen Weg.","*formt einen harmonischen Kreis aus Eis.*"],"ARCANE":["Wissen ist eine Gabe und eine Verantwortung.","*zeichnet eine schwebende geometrische Figur.*"]},"DWARF":{"FIRE":["Mit dem Feuer krieg ich auch die Esse wieder flott!","*prüft die Glut mit dem Blick eines Schmieds.*"],"FROST":["Der Frost ist hart. Härter ist nur unser Fels.","*klopft eine Eisrune auf ihre Festigkeit ab.*"],"ARCANE":["Eine gute Formel muss was aushalten können.","*klopft gegen eine schwebende Rune wie gegen ein Fass.*"]}}
GENERAL = {"enUS": {"GNOME":["The calculations say this is perfectly safe.","*adjusts an impossibly small measuring instrument.*"],"HUMAN":["Control comes before power.","*recites an academy formula with care.*"],"HIGH_ELF":["The ley lines still remember.","*listens to an ancient arcane current.*"],"BLOODELF":["Perfection is a matter of precision.","*adjusts a flawless glowing rune.*"],"NIGHTELF":["Ancient power requires restraint.","*traces a symbol beneath the stars.*"],"UNDEAD":["A useful formula outlives its author.","*turns a dusty page with a skeletal finger.*"],"TROLL":["The ancestors taught us more than scrolls ever could.","*traces an old spirit sign.*"],"ORC":["Strong magic needs a stronger will.","*grips a flickering glyph firmly.*"],"DRAENEI":["Knowledge carries responsibility.","*shapes a calm, luminous pattern.*"],"DWARF":["Good magic should stand up to a hammer blow.","*taps an arcane sigil like a barrel.*"]}, "frFR": {"GNOME":["Selon mes calculs, tout est parfaitement sûr.","*ajuste un minuscule instrument de mesure.*"],"HUMAN":["La maîtrise précède la puissance.","*récite soigneusement une formule académique.*"],"HIGH_ELF":["Les lignes telluriques ont bonne mémoire.","*écoute un ancien courant arcanique.*"],"BLOODELF":["La perfection exige de la précision.","*ajuste une rune lumineuse impeccable.*"],"NIGHTELF":["Un ancien pouvoir exige de la retenue.","*dessine un symbole sous les étoiles.*"],"UNDEAD":["Une bonne formule survit à son auteur.","*tourne une page poussiéreuse d'un doigt osseux.*"],"TROLL":["Les ancêtres en savent plus que les parchemins.","*trace un vieux signe des esprits.*"],"ORC":["Une magie puissante exige une volonté ferme.","*stabilise un glyphe vacillant.*"],"DRAENEI":["Le savoir implique des responsabilités.","*dessine une forme lumineuse et paisible.*"],"DWARF":["Une bonne magie doit résister à un coup de marteau.","*tapote un signe arcanique comme un tonneau.*"]}}
SCHOOLS = ("FIRE", "FROST", "ARCANE")

def school_for(key: str) -> str:
    theme = theme_for(key)
    if theme in SCHOOLS:
        return theme
    # Utility magic and buffs draw on the character's arcane voice.
    return "ARCANE"

def voice_lines(lang: str, race: str, key: str) -> list[str]:
    if race not in RACES:
        return []
    if lang == "deDE":
        return list(GERMAN[race][school_for(key)])
    return list(GENERAL.get(lang, {}).get(race, []))
